package music.resonance.mobile;
import org.junit.Test;import org.json.*;import static org.junit.Assert.*;
public class RecordingFallbackTest {
 @Test public void musicVideoSearchAndMatchingIncludeClipLabelsButNotDifferentVersions()throws Exception{
  JSONObject original=Json.object("title","Moonlight","artist","Mira - Topic","duration",210,"youtubeId","AAAAAAAAAAA");assertEquals("ytsearch8:Mira Moonlight official music video",RecordingFallback.queries(original).get(2));
  for(String suffix:new String[]{"(Official Music Video) [4K]","[Official Video HD]","(Official MV)","(Clip officiel)","| Official Music Video"}){JSONObject clip=Json.object("id","BBBBBBBBBBB","title","Mira - Moonlight "+suffix,"channel","MiraVEVO","duration",211);assertTrue(suffix,RecordingFallback.matches(original,clip));assertTrue(suffix,RecordingFallback.musicVideo(clip));}
  JSONObject clip=Json.object("id","BBBBBBBBBBB","title","Mira - Moonlight (Official Music Video)","channel","Mira","duration",260);assertFalse(RecordingFallback.matches(original,clip));clip.put("duration",210).put("title","Mira - Moonlight (Live) (Official Video)");assertFalse(RecordingFallback.matches(original,clip));clip.put("title","Mira - Moonlight (Remix) [4K]");assertFalse(RecordingFallback.matches(original,clip));assertEquals("music video",RecordingFallback.clean("Music Video"));
 }
 @Test public void clipDownloadsAlwaysExtractAudioAndPreserveCompactPreference(){
  for(String format:new String[]{"original","compact"}){com.yausername.youtubedl_android.YoutubeDLRequest request=new com.yausername.youtubedl_android.YoutubeDLRequest("https://www.youtube.com/watch?v=BBBBBBBBBBB");Downloads.audioOptions(request,format);assertEquals("bestaudio/best",request.getOption("-f"));assertTrue(request.hasOption("-x"));assertTrue(request.hasOption("--no-keep-video"));assertEquals(format.equals("compact")?"opus":"best",request.getOption("--audio-format"));assertEquals(format.equals("compact"),request.hasOption("--audio-quality"));if(format.equals("compact"))assertEquals("128K",request.getOption("--audio-quality"));}
 }
 @Test public void exactSearchRecoversTitlesHiddenByBroadResults()throws Exception{JSONObject t=Json.object("title","The Archive","artist","Aineth - Topic","duration",319,"youtubeId","AAAAAAAAAAA");assertEquals("ytsearch8:\"The Archive\" \"Aineth\"",RecordingFallback.queries(t).get(1));JSONObject c=Json.object("id","BBBBBBBBBBB","title","The Archive","channel","Aineth - Topic","duration",319);assertTrue(RecordingFallback.matches(t,c));c.put("title","THE ARCHIVE [REMASTERED]");assertFalse(RecordingFallback.matches(t,c));assertEquals("music",RecordingFallback.clean("Music"));assertEquals("audio video",RecordingFallback.clean("Audio Video"));}
 @Test public void repostCreditIsTakenFromTitle()throws Exception{JSONObject t=Json.object("title","Head Splitter - Petrochem","artist","Repost channel","duration",240);assertTrue(RecordingFallback.matches(t,Json.object("id","BBBBBBBBBBB","title","Petrochem","channel","Head Splitter","duration",241)));}
 @Test public void similarArtistOrLongerTitleDoesNotQualify()throws Exception{JSONObject original=new JSONObject().put("title","Moonlight").put("artist","Mira").put("duration",210),other=new JSONObject().put("id","BBBBBBBBBBB").put("title","Moonlight").put("channel","Miranda").put("duration",210);assertFalse(RecordingFallback.matches(original,other));other.put("channel","Mira").put("title","Moonlight Sonata");assertFalse(RecordingFallback.matches(original,other));}
 @Test public void temporaryBlocksNeverSearchAlternatives(){for(String raw:new String[]{"Video unavailable. HTTP Error 429","Video unavailable: try again later","Sign in to confirm you’re not a bot"}){assertTrue(DownloadFailures.pausesBatch(raw));assertFalse(RecordingFallback.unavailable(raw));}assertTrue(RecordingFallback.unavailable("Video unavailable"));assertFalse(RecordingFallback.unavailable("HTTP Error 403"));}
 @Test public void onlyCloseRecordingVersionsMatch()throws Exception{JSONObject track=new JSONObject().put("title","Moonlight").put("artist","Mira").put("duration",210).put("youtubeId","AAAAAAAAAAA"),candidate=new JSONObject().put("title","Mira - Moonlight (Official Audio)").put("channel","Mira - Topic").put("duration",211).put("id","BBBBBBBBBBB");assertTrue(RecordingFallback.matches(track,candidate));candidate.put("title","Moonlight (Live)");assertFalse(RecordingFallback.matches(track,candidate));candidate.put("title","Moonlight").put("duration",270);assertFalse(RecordingFallback.matches(track,candidate));candidate.put("duration",210).put("channel","Someone Else");assertFalse(RecordingFallback.matches(track,candidate));}
}
